// Some portions generated by Claude
/**
 * Stepped routes: when the best single bend still crosses a card, or arcs further than most of the arrow's length
 * (a grid of cards leaves no other way round), the arrow follows the gaps between cards instead, with horizontal and
 * vertical legs and rounded corners. Routes are searched with A* over lines that run through the middle of the gaps.
 */
import { quadraticIntersectsBounds, segmentIntersectsBounds } from "./graph-curve-collision.ts";
import { computeEdgeLanes, computeEdgePorts, edgeGeometry, edgePortKey, graphNodeSize } from "./graph-geometry.ts";
import { LAYOUT_SPACING as gap } from "./graph-layout-spacing.ts";
import type { EdgeRoute, GraphEdge, GraphNode, PointerPosition } from "./graph-types.ts";

/** A bend larger than this share of the distance between the cards reads as a detour around the drawing. */
const DETOUR_RATIO = 0.8;
/** Distance a route keeps from cards it passes. */
const CLEARANCE = 8;
const CORNER_COST = 70;
/** Cost per pixel of running along a leg another route already uses. */
const SHARED_COST = 1.5;
const REGION_MARGIN = 360;
const OBSTACLE_LIMIT = 160;
/** A stepped route longer than this many times the straight distance (plus a constant) is not worth taking. */
const LENGTH_LIMIT = 3;

type Box = { x: number; y: number; width: number; height: number };
type Segment = [PointerPosition, PointerPosition];

const bounds = (box: Box, padding: number) => ({
  minX: box.x - box.width / 2 - padding, minY: box.y - box.height / 2 - padding,
  maxX: box.x + box.width / 2 + padding, maxY: box.y + box.height / 2 + padding,
});
const inside = (box: Box, p: PointerPosition, padding = 0) =>
  Math.abs(p.x - box.x) < box.width / 2 + padding && Math.abs(p.y - box.y) < box.height / 2 + padding;
const length = (points: readonly PointerPosition[]) =>
  points.slice(1).reduce((sum, p, i) => sum + Math.abs(p.x - points[i].x) + Math.abs(p.y - points[i].y), 0);

/** Where the segment from a (inside the box) to b (outside) crosses the box's border, pushed out a little. */
function exitPoint(box: Box, a: PointerPosition, b: PointerPosition) {
  const b0 = bounds(box, 1.5);
  let t = 1;
  if (b.x > b0.maxX) t = Math.min(t, (b0.maxX - a.x) / (b.x - a.x));
  if (b.x < b0.minX) t = Math.min(t, (b0.minX - a.x) / (b.x - a.x));
  if (b.y > b0.maxY) t = Math.min(t, (b0.maxY - a.y) / (b.y - a.y));
  if (b.y < b0.minY) t = Math.min(t, (b0.minY - a.y) / (b.y - a.y));
  t = Math.max(0, Math.min(1, t));
  return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
}

class Heap {
  private items: Array<[number, number]> = [];
  push(cost: number, value: number) {
    const items = this.items;
    items.push([cost, value]);
    for (let i = items.length - 1; i > 0;) {
      const parent = (i - 1) >> 1;
      if (items[parent][0] <= items[i][0]) break;
      [items[parent], items[i]] = [items[i], items[parent]];
      i = parent;
    }
  }
  pop() {
    const items = this.items, top = items[0], last = items.pop()!;
    if (items.length) {
      items[0] = last;
      for (let i = 0; ;) {
        const left = i * 2 + 1, right = left + 1;
        let smallest = i;
        if (left < items.length && items[left][0] < items[smallest][0]) smallest = left;
        if (right < items.length && items[right][0] < items[smallest][0]) smallest = right;
        if (smallest === i) break;
        [items[smallest], items[i]] = [items[i], items[smallest]];
        i = smallest;
      }
    }
    return top;
  }
  get size() {return this.items.length;}
}

/** Collinear overlap of an axis-aligned leg with legs other routes already use. */
function sharedLength(a: PointerPosition, b: PointerPosition, used: readonly Segment[]) {
  let shared = 0;
  for (const [c, d] of used) {
    if (Math.abs(a.y - b.y) < 0.5 && Math.abs(c.y - d.y) < 0.5 && Math.abs(a.y - c.y) < 4) {
      shared += Math.max(0, Math.min(Math.max(a.x, b.x), Math.max(c.x, d.x)) - Math.max(Math.min(a.x, b.x), Math.min(c.x, d.x)));
    } else if (Math.abs(a.x - b.x) < 0.5 && Math.abs(c.x - d.x) < 0.5 && Math.abs(a.x - c.x) < 4) {
      shared += Math.max(0, Math.min(Math.max(a.y, b.y), Math.max(c.y, d.y)) - Math.max(Math.min(a.y, b.y), Math.min(c.y, d.y)));
    }
  }
  return shared;
}

/** A stepped route from the source card to the target card around the obstacles, or null. */
export function steppedRoute(source: Box, target: Box, obstacles: readonly Box[], used: readonly Segment[] = []): PointerPosition[] | null {
  const region = {
    minX: Math.min(source.x, target.x) - REGION_MARGIN, maxX: Math.max(source.x, target.x) + REGION_MARGIN,
    minY: Math.min(source.y, target.y) - REGION_MARGIN, maxY: Math.max(source.y, target.y) + REGION_MARGIN,
  };
  const relevant = obstacles.filter(o => o.x + o.width / 2 > region.minX && o.x - o.width / 2 < region.maxX && o.y + o.height / 2 > region.minY && o.y - o.height / 2 < region.maxY);
  if (relevant.length > OBSTACLE_LIMIT) return null;
  const within = (value: number, low: number, high: number) => value >= low && value <= high;
  const xs = [...new Set([source.x, target.x, ...relevant.flatMap(o => [o.x - o.width / 2 - gap.nodeGapX / 2, o.x + o.width / 2 + gap.nodeGapX / 2]),
    region.minX, region.maxX].filter(x => within(x, region.minX, region.maxX)))].sort((a, b) => a - b);
  const ys = [...new Set([source.y, target.y, ...relevant.flatMap(o => [o.y - o.height / 2 - gap.nodeGapY / 2, o.y + o.height / 2 + gap.nodeGapY / 2]),
    region.minY, region.maxY].filter(y => within(y, region.minY, region.maxY)))].sort((a, b) => a - b);
  const padded = relevant.map(o => bounds(o, CLEARANCE));
  const blocked = (p: PointerPosition) => relevant.some(o => inside(o, p, CLEARANCE));
  const free = (a: PointerPosition, b: PointerPosition) => !padded.some(box => segmentIntersectsBounds(a, b, box));
  const nx = xs.length, ny = ys.length;
  const point = (index: number) => ({ x: xs[Math.floor(index / ny)], y: ys[index % ny] });
  const start = xs.indexOf(source.x) * ny + ys.indexOf(source.y), goal = xs.indexOf(target.x) * ny + ys.indexOf(target.y);
  // States are (grid point, direction of arrival): 0 none, 1 horizontal, 2 vertical.
  const best = new Float64Array(nx * ny * 3).fill(Infinity), previous = new Int32Array(nx * ny * 3).fill(-1);
  const heuristic = (index: number) => {const p = point(index); return Math.abs(p.x - target.x) + Math.abs(p.y - target.y);};
  const heap = new Heap();
  best[start * 3] = 0;
  heap.push(heuristic(start), start * 3);
  const freeMemo = new Map<number, boolean>();
  let reached = -1;
  while (heap.size) {
    const [, state] = heap.pop();
    const index = Math.floor(state / 3), direction = state % 3, cost = best[state];
    if (index === goal) {reached = state; break;}
    const i = Math.floor(index / ny), j = index % ny, here = point(index);
    for (const [di, dj, d] of [[1, 0, 1], [-1, 0, 1], [0, 1, 2], [0, -1, 2]] as const) {
      const ni = i + di, nj = j + dj;
      if (ni < 0 || nj < 0 || ni >= nx || nj >= ny) continue;
      const next = ni * ny + nj, there = point(next);
      if (next !== goal && blocked(there)) continue;
      const key = Math.min(index, next) * nx * ny + Math.max(index, next);
      let open = freeMemo.get(key);
      if (open === undefined) {open = free(here, there); freeMemo.set(key, open);}
      if (!open) continue;
      const step = Math.abs(there.x - here.x) + Math.abs(there.y - here.y);
      const total = cost + step + (direction && direction !== d ? CORNER_COST : 0) + sharedLength(here, there, used) * SHARED_COST;
      const nextState = next * 3 + d;
      if (total < best[nextState]) {
        best[nextState] = total;
        previous[nextState] = state;
        heap.push(total + heuristic(next), nextState);
      }
    }
  }
  if (reached < 0) return null;
  const path: PointerPosition[] = [];
  for (let state = reached; state >= 0; state = previous[state]) path.push(point(Math.floor(state / 3)));
  path.reverse();
  // Drop points on straight runs.
  const corners = path.filter((p, i) => i === 0 || i === path.length - 1 ||
    !((Math.abs(path[i - 1].x - p.x) < 0.01 && Math.abs(path[i + 1].x - p.x) < 0.01) || (Math.abs(path[i - 1].y - p.y) < 0.01 && Math.abs(path[i + 1].y - p.y) < 0.01)));
  // Start where the route leaves the source card and end where it first enters the target card.
  let first = 0;
  while (first < corners.length - 1 && inside(source, corners[first + 1])) first++;
  let last = corners.length - 1;
  for (let k = first; k < corners.length - 1; k++) if (inside(target, corners[k + 1])) {last = k + 1; break;}
  const trimmed = corners.slice(first, last + 1);
  if (trimmed.length < 2) return null;
  trimmed[0] = exitPoint(source, trimmed[0], trimmed[1]);
  trimmed[trimmed.length - 1] = exitPoint(target, trimmed[trimmed.length - 1], trimmed[trimmed.length - 2]);
  return trimmed;
}

/**
 * Stepped routes for the arrows a single bend cannot draw well: the bend still crosses a card, or it arcs further than
 * `DETOUR_RATIO` of the distance between the cards. Parallel arrows and loops keep their bends.
 */
export function steppedRoutes(nodes: readonly GraphNode[], edges: readonly GraphEdge[], bends: ReadonlyMap<string, number>) {
  const routes = new Map<string, EdgeRoute>();
  if (nodes.length > 350 || edges.length > 1600) return routes;
  const placed = nodes.filter(node => node.x !== undefined && node.y !== undefined);
  const byId = new Map(placed.map(node => [node.id, node]));
  const boxes = new Map(placed.map(node => [node.id, { x: node.x!, y: node.y!, ...graphNodeSize(node) }]));
  const lanes = computeEdgeLanes([...edges]), ports = computeEdgePorts([...placed], [...edges]);
  const used: Segment[] = [];
  for (const edge of [...edges].sort((a, b) => a.id.localeCompare(b.id))) {
    const source = byId.get(edge.source), target = byId.get(edge.target);
    if (!source || !target || edge.source === edge.target || (lanes.get(edge.id) ?? 0) !== 0) continue;
    const bend = bends.get(edge.id) ?? 0, distance = Math.hypot(target.x! - source.x!, target.y! - source.y!);
    const curve = edgeGeometry(source, target, bend, ports.get(edgePortKey(edge.id, edge.source)), ports.get(edgePortKey(edge.id, edge.target)));
    const obstacles = [...boxes].filter(([id]) => id !== edge.source && id !== edge.target).map(([, box]) => box);
    const crossesCard = obstacles.some(box => quadraticIntersectsBounds(curve, bounds(box, 0)));
    if (!crossesCard && Math.abs(bend) <= DETOUR_RATIO * distance) continue;
    const points = steppedRoute(boxes.get(edge.source)!, boxes.get(edge.target)!, obstacles, used);
    if (!points || length(points) > LENGTH_LIMIT * distance + 200) continue;
    routes.set(edge.id, { source: { x: source.x!, y: source.y! }, target: { x: target.x!, y: target.y! }, points });
    for (let i = 1; i < points.length; i++) used.push([points[i - 1], points[i]]);
  }
  return routes;
}
